/**
 * The incident any incident event names: `data` itself for lifecycle
 * events, `data.incident` for sub-resources. Mirrors the continuation
 * selector, so a hook's `ctx.incidentId` names the session's incident.
 */
export function pagerDutyEventIncident(event) {
    const data = asRecord(event.data);
    const record = asRecord(data?.incident) ??
        (data?.type === "incident" || event.resource_type === "incident" ? data : undefined);
    const id = asNonEmptyString(record?.id);
    if (id === undefined) {
        return undefined;
    }
    return { id, incidentKey: asNonEmptyString(record?.incident_key) };
}
const PAGERDUTY_HOST = /^([a-z0-9][a-z0-9-]*)\.(?:[a-z]{2}\.)?pagerduty\.com$/i;
/**
 * The account subdomain (`acme` for `acme.pagerduty.com` or
 * `acme.eu.pagerduty.com`) from the first PagerDuty web URL the event
 * carries: the incident's, the agent's, or the data's own.
 */
export function pagerDutyAccountSubdomain(event) {
    const data = asRecord(event.data);
    const candidates = [
        asRecord(data?.incident)?.html_url,
        data?.html_url,
        asRecord(event.agent)?.html_url,
        asRecord(data?.service)?.html_url,
    ];
    for (const candidate of candidates) {
        const url = asNonEmptyString(candidate);
        if (url === undefined) {
            continue;
        }
        try {
            const match = PAGERDUTY_HOST.exec(new URL(url).hostname);
            if (match?.[1] !== undefined) {
                return match[1].toLowerCase();
            }
        }
        catch {
            // Not a URL; try the next one.
        }
    }
    return undefined;
}
